function useProvidersWithSync() {
  const { providers, mutate } = useProviders();
  const [syncActive, setSyncActive] = useAtom(providerSyncActiveAtom);
  reactExports.useEffect(() => {
    providerSyncClient.initialize();
    setSyncActive(true);
    const unsubscribe = providerSyncClient.addProviderListener((message) => {
      switch (message.type) {
        case "provider_created":
        case "provider_updated":
        case "provider_deleted": {
          mutate();
          break;
        }
      }
    });
    return () => {
      unsubscribe();
      setSyncActive(false);
    };
  }, [mutate, setSyncActive]);
  return {
    providers,
    syncActive,
    mutate
  };
}
